import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { Frame, SessionInfo, View } from '../types'
import { parseTranscript, projectFolderName, titleOf } from './parse'

const PANE = 'replay-theater'
const TITLE = 'Replay Theater'
const TICK_MS = 400
const MAX_READ = 4 * 1024 * 1024 - 64 * 1024
const LISTED = 15

const view = atom({ plugin: 'replay-theater', key: 'view' } as const, 'list')
const sessions = atom({ plugin: 'replay-theater', key: 'sessions' } as const, [])
const title = atom({ plugin: 'replay-theater', key: 'title' } as const, '')
const frames = atom({ plugin: 'replay-theater', key: 'frames' } as const, [])
const cursor = atom({ plugin: 'replay-theater', key: 'cursor' } as const, 0)
const isPlaying = atom({ plugin: 'replay-theater', key: 'isPlaying' } as const, false)
const speed = atom({ plugin: 'replay-theater', key: 'speed' } as const, 1)
const note = atom({ plugin: 'replay-theater', key: 'note' } as const, null)

const SPEEDS = [1, 2, 4]

const LABEL: Record<Frame['kind'], { name: string; color: string }> = {
  prompt: { name: 'You', color: 'suggestion' },
  reply: { name: 'Claude', color: 'claude' },
  tool: { name: 'Tool', color: 'warning' },
  result: { name: 'Result', color: 'subtle' },
}

const transcriptsFolder = async ($: EngineInterface): Promise<string> => {
  const configured = await $.env.get('CLAUDE_CONFIG_DIR')
  const home = (await $.env.get('HOME')) ?? ''
  const config = configured ?? `${home}/.claude`
  return `${config}/projects/${projectFolderName(await $.session.root())}`
}

// The start of a file, for one too large to read whole or when only its title is needed.
const head = async ($: EngineInterface, path: string, bytes: number): Promise<string> => {
  const { stdout } = await $.process.run(['head', '-c', String(bytes), path])
  return stdout
}

const loadList = async ($: EngineInterface): Promise<void> => {
  await update($, note, () => 'Looking for sessions…')
  try {
    const folder = await transcriptsFolder($)
    const current = await $.session.id()
    const entries = (await $.fs.list(folder))
      .filter(one => one.kind === 'file' && one.name.endsWith('.jsonl') && one.size > 0)
      .sort((a, b) => b.mtimeMs - a.mtimeMs)
      .slice(0, LISTED)
    const found: SessionInfo[] = []
    for (const one of entries) {
      const id = one.name.slice(0, -'.jsonl'.length)
      const path = `${folder}/${one.name}`
      const text = await head($, path, 256 * 1024).catch(() => '')
      found.push({ id, title: titleOf(text), mtimeMs: one.mtimeMs, size: one.size, isCurrent: id === current })
    }
    await update($, sessions, () => found)
    await update($, note, () => (found.length === 0 ? 'No past sessions found for this project.' : null))
  } catch (error) {
    await update($, note, () => `Could not list sessions: ${String(error)}`)
  }
}

const openSession = async ($: EngineInterface, session: SessionInfo): Promise<void> => {
  await update($, isPlaying, () => false)
  await update($, note, () => 'Loading…')
  try {
    const path = `${await transcriptsFolder($)}/${session.id}.jsonl`
    const isWhole = session.size <= MAX_READ
    const text = isWhole ? await $.fs.read(path) : await head($, path, MAX_READ)
    const parsed = parseTranscript(text)
    await update($, frames, () => parsed)
    await update($, title, () => session.title)
    await update($, cursor, () => 0)
    await update($, view, () => 'stage')
    await update($, note, () => (isWhole ? null : 'Large session: only its first 4 MB is replayed.'))
  } catch (error) {
    await update($, note, () => `Could not open that session: ${String(error)}`)
  }
}

const step = async ($: EngineInterface, by: number): Promise<void> => {
  const count = (await read($, frames)).length
  await update($, cursor, at => Math.max(0, Math.min(count - 1, at + by)))
}

const togglePlay = async ($: EngineInterface): Promise<void> => {
  const count = (await read($, frames)).length
  if ((await read($, cursor)) >= count - 1) await update($, cursor, () => 0)
  await update($, isPlaying, on => !on)
}

// Cuts text to whole lines that fit the pane.
const clip = (text: string, lines: number, columns: number): string[] => {
  const out: string[] = []
  for (const raw of text.split('\n')) {
    let rest = raw
    do {
      out.push(rest.slice(0, columns))
      rest = rest.slice(columns)
    } while (rest.length > 0 && out.length < lines)
    if (out.length >= lines) break
  }
  const isCut = out.length >= lines && out.join('\n').length < text.length
  const last = out.at(-1)
  if (isCut && last !== undefined) out[out.length - 1] = `${last.slice(0, Math.max(0, columns - 1))}…`
  return out.slice(0, lines)
}

const when = (iso: string | undefined): string => {
  if (iso === undefined) return ''
  const date = new Date(iso)
  return Number.isNaN(date.getTime()) ? '' : date.toTimeString().slice(0, 8)
}

const ago = (ms: number, now: number): string => {
  const minutes = Math.round((now - ms) / 60000)
  if (minutes < 60) return `${minutes}m ago`
  if (minutes < 60 * 48) return `${Math.round(minutes / 60)}h ago`
  return `${Math.round(minutes / 1440)}d ago`
}

const sizeOf = (bytes: number): string =>
  bytes < 1024 * 1024 ? `${Math.max(1, Math.round(bytes / 1024))} KB` : `${(bytes / 1024 / 1024).toFixed(1)} MB`

export const register: Register = on => {
  let ticks = 0

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'replay',
      description: 'Replay a past session of this project step by step in a pane',
    })
    await update($, isPlaying, () => false)

    // One heartbeat drives playback: at 1x a frame every 1.6 s, 4x every 0.4 s.
    $.clock.every(TICK_MS, () => {
      void (async () => {
        if (!(await read($, isPlaying))) return
        ticks += 1
        if (ticks % (4 / (await read($, speed))) !== 0) return
        const count = (await read($, frames)).length
        const at = await read($, cursor)
        if (at >= count - 1) {
          await update($, isPlaying, () => false)
          return
        }
        await update($, cursor, n => n + 1)
      })()
    })

    return next(e)
  })

  on('command.run', { command: 'replay' }, async $ => {
    await update($, view, () => 'list')
    await $.ui.open({ id: PANE, title: TITLE })
    await loadList($)

    return { text: 'Replay Theater opened. Pick a session to replay.' }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text, Button } = $.ui.resolve(e)
    const columns = Math.max(20, e.props.bodyColumns - 2)
    const rows = Math.max(10, (e.viewport?.rows ?? 30) - 4)
    const current: View = await read($, view)
    const message = await read($, note)

    if (current === 'list') {
      const list = await read($, sessions)
      const now = await $.clock.now()

      return (
        <Box flexDirection="column" gap={1}>
          <Box gap={2}>
            <Text bold>Pick a session to replay</Text>
            <Button key="refresh" label="Refresh" hotkey="r" onPress={() => loadList($)} />
          </Box>
          {message !== null && <Text dimColor>{message}</Text>}
          <Box flexDirection="column">
            {list.map(one => (
              <Box key={`row-${one.id}`} gap={1}>
                <Button
                  key={`s-${one.id}`}
                  label={clip(one.title, 1, Math.max(10, columns - 28))[0] ?? one.id}
                  plain
                  onPress={() => openSession($, one)}
                />
                <Text dimColor>
                  {`${ago(one.mtimeMs, now)} · ${sizeOf(one.size)}${one.isCurrent ? ' · this session' : ''}`}
                </Text>
              </Box>
            ))}
          </Box>
        </Box>
      )
    }

    const all = await read($, frames)
    const at = await read($, cursor)
    const playing = await read($, isPlaying)
    const pace = await read($, speed)
    const name = await read($, title)
    const frame = all[at]

    // The stage: earlier frames as one-line context, the current one in full.
    const stageRows = Math.max(4, rows - 8)
    const currentLines = frame === undefined ? [] : clip(frame.text || '(empty)', Math.max(3, stageRows - 4), columns)
    const contextRows = Math.max(0, stageRows - currentLines.length - 1)
    const earlier = all.slice(Math.max(0, at - contextRows), at)

    return (
      <Box flexDirection="column" gap={1}>
        <Box flexDirection="column">
          <Text bold wrap="truncate-end">{name || 'Untitled session'}</Text>
          <Text dimColor>
            Frame {all.length === 0 ? 0 : at + 1} of {all.length}
            {frame?.at ? ` · ${when(frame.at)}` : ''} · {pace}x
          </Text>
        </Box>
        {message !== null && <Text color="warning">{message}</Text>}
        {all.length === 0 ? (
          <Text dimColor>This session has nothing to replay.</Text>
        ) : (
          <Box flexDirection="column">
            {earlier.map(one => (
              <Text dimColor wrap="truncate-end">
                {LABEL[one.kind].name}
                {one.tool ? ` ${one.tool}` : ''}: {one.text.split('\n')[0]}
              </Text>
            ))}
            {frame !== undefined && (
              <Box flexDirection="column" marginTop={earlier.length > 0 ? 1 : 0}>
                <Text bold color={LABEL[frame.kind].color}>
                  {LABEL[frame.kind].name}
                  {frame.tool ? ` · ${frame.tool}` : ''}
                </Text>
                {currentLines.map(line => (
                  <Text>{line === '' ? ' ' : line}</Text>
                ))}
              </Box>
            )}
          </Box>
        )}
        <Box gap={1} flexWrap="wrap">
          <Button key="start" label="|<" hotkey="h" onPress={() => update($, cursor, () => 0)} />
          <Button key="back" label="< Back" hotkey="b" onPress={() => step($, -1)} />
          <Button
            key="play"
            variant="primary"
            label={playing ? 'Pause' : 'Play'}
            hotkey="p"
            onPress={() => togglePlay($)}
          />
          <Button key="next" label="Next >" hotkey="n" onPress={() => step($, 1)} />
          <Button key="end" label=">|" hotkey="e" onPress={() => step($, all.length)} />
          <Button
            key="speed"
            label={`Speed ${pace}x`}
            hotkey="s"
            onPress={() => update($, speed, s => SPEEDS[(SPEEDS.indexOf(s) + 1) % SPEEDS.length] ?? 1)}
          />
          <Button
            key="list"
            label="Sessions"
            hotkey="l"
            onPress={async () => {
              await update($, isPlaying, () => false)
              await update($, view, () => 'list')
              await loadList($)
            }}
          />
        </Box>
      </Box>
    )
  })
}

