import type { Frame } from '../types'

const MAX_TEXT = 2000
const MAX_FRAMES = 3000

type Block = {
  type?: string
  text?: string
  name?: string
  input?: Record<string, unknown>
  content?: unknown
  is_error?: boolean
}

type Entry = {
  type?: string
  isMeta?: boolean
  isSidechain?: boolean
  timestamp?: string
  message?: { content?: string | Block[] }
}

// The folder Claude Code keeps a project's transcripts in, named after its root.
export const projectFolderName = (root: string): string =>
  root.replace(/[^a-zA-Z0-9]/g, '-')

const cut = (text: string): string =>
  text.length > MAX_TEXT ? `${text.slice(0, MAX_TEXT)}…` : text

// Rows the engine injects rather than the person typed.
const isNoise = (text: string): boolean => {
  const t = text.trimStart()
  return (
    t === '' ||
    t.startsWith('<system-reminder>') ||
    t.startsWith('<local-command-') ||
    t.startsWith('Caveat: The messages below') ||
    t.startsWith('[Request interrupted')
  )
}

// "/name args" for a slash command row, the text itself otherwise.
const promptText = (text: string): string => {
  const name = /<command-name>([^<]*)<\/command-name>/.exec(text)?.[1]
  if (name === undefined) return text.trim()
  const args = /<command-args>([^<]*)<\/command-args>/.exec(text)?.[1] ?? ''
  return `${name.startsWith('/') ? name : `/${name}`} ${args}`.trim()
}

const toolSummary = (input: Record<string, unknown> | undefined): string => {
  if (input === undefined) return ''
  for (const key of ['description', 'command', 'file_path', 'pattern', 'url', 'query', 'prompt']) {
    const value = input[key]
    if (typeof value === 'string' && value !== '') return value
  }
  const first = Object.values(input).find(v => typeof v === 'string')
  return typeof first === 'string' ? first : ''
}

const resultText = (content: unknown): string => {
  if (typeof content === 'string') return content
  if (!Array.isArray(content)) return ''
  return content
    .map(b => (b && typeof b === 'object' && 'text' in b ? String((b as Block).text ?? '') : '[image]'))
    .join('\n')
}

const parseLine = (line: string): Entry | undefined => {
  try {
    const value: unknown = JSON.parse(line)
    return value && typeof value === 'object' ? (value as Entry) : undefined
  } catch {
    return undefined
  }
}

// Turns a transcript's JSONL into the frames the stage plays: the person's
// prompts, Claude's replies, its tool calls and their results.
export const parseTranscript = (jsonl: string): Frame[] => {
  const frames: Frame[] = []
  for (const line of jsonl.split('\n')) {
    if (frames.length >= MAX_FRAMES) break
    const entry = parseLine(line)
    if (entry === undefined || entry.isMeta || entry.isSidechain) continue
    if (entry.type !== 'user' && entry.type !== 'assistant') continue
    const at = entry.timestamp
    const content = entry.message?.content
    if (typeof content === 'string') {
      if (entry.type === 'user' && !isNoise(content)) {
        frames.push({ kind: 'prompt', text: cut(promptText(content)), at })
      }
      continue
    }
    for (const block of content ?? []) {
      if (block.type === 'text' && typeof block.text === 'string') {
        if (entry.type === 'assistant') {
          if (block.text.trim() !== '') frames.push({ kind: 'reply', text: cut(block.text.trim()), at })
        } else if (!isNoise(block.text)) {
          frames.push({ kind: 'prompt', text: cut(promptText(block.text)), at })
        }
      } else if (block.type === 'tool_use') {
        frames.push({ kind: 'tool', tool: block.name ?? 'tool', text: cut(toolSummary(block.input)), at })
      } else if (block.type === 'tool_result') {
        const text = resultText(block.content).trim()
        frames.push({ kind: 'result', text: cut(block.is_error ? `Error: ${text}` : text || '(no output)'), at })
      }
    }
  }
  return frames
}

// The first prompt the person typed, as the session's title.
export const titleOf = (jsonl: string): string => {
  for (const line of jsonl.split('\n')) {
    const entry = parseLine(line)
    if (entry?.type === 'summary' && typeof (entry as { summary?: unknown }).summary === 'string') {
      return (entry as { summary: string }).summary
    }
  }
  const first = parseTranscript(jsonl).find(f => f.kind === 'prompt')
  return first?.text.split('\n')[0] ?? '(no prompt)'
}

