export type FrameKind = 'prompt' | 'reply' | 'tool' | 'result'

export type Frame = { kind: FrameKind; text: string; tool?: string; at?: string }

export type SessionInfo = {
  id: string
  title: string
  mtimeMs: number
  size: number
  isCurrent: boolean
}

export type View = 'list' | 'stage'

declare module 'claude-code' {
  interface PluginState {
    'replay-theater': {
      view: View
      sessions: SessionInfo[]
      title: string
      frames: Frame[]
      cursor: number
      isPlaying: boolean
      speed: number
      note: string | null
    }
  }
}
